export function findNearestRoadCorridor(lat: number, lng: number, thresholdMeters = 400): RoadCorridor | null {
  function distMeters(lat1: number, lon1: number, lat2: number, lon2: number) {
    const R = 6371e3;
    const phi1 = (lat1 * Math.PI) / 180;
    const phi2 = (lat2 * Math.PI) / 180;
    const deltaPhi = ((lat2 - lat1) * Math.PI) / 180;
    const deltaLambda = ((lon2 - lon1) * Math.PI) / 180;
    const a =
      Math.sin(deltaPhi / 2) * Math.sin(deltaPhi / 2) +
      Math.cos(phi1) * Math.cos(phi2) * Math.sin(deltaLambda / 2) * Math.sin(deltaLambda / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  let minDistance = Infinity;
  let matchedCorridor: RoadCorridor | null = null;

  for (const corridor of ROAD_CORRIDORS) {
    for (const [cLng, cLat] of corridor.centerline) {
      const d = distMeters(lat, lng, cLat, cLng);
      if (d < minDistance) {
        minDistance = d;
        if (d <= thresholdMeters) {
          matchedCorridor = corridor;
        }
      }
    }
  }

  return minDistance <= thresholdMeters ? matchedCorridor : null;
}
